package com.snaphere.api.auth;
import com.fasterxml.jackson.databind.ObjectMapper; import com.snaphere.api.common.error.*; import org.springframework.stereotype.Service; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.*; import java.util.*;
@Service class JwtService {
 private final byte[] secret; private final ObjectMapper mapper; JwtService(AuthProperties p,ObjectMapper mapper){if(p.jwtSecret()==null||p.jwtSecret().getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("SNAPHERE_JWT_SECRET must contain at least 32 bytes");secret=p.jwtSecret().getBytes(StandardCharsets.UTF_8);this.mapper=mapper;}
 String issue(User user, UserDevice device){try{long exp=Instant.now().plus(Duration.ofHours(2)).getEpochSecond();String h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}"),pl=b64(mapper.writeValueAsString(Map.of("sub",user.getId().toString(),"deviceId",device.getId().toString(),"role",user.getRole().name(),"exp",exp,"iss","snaphere")));return h+"."+pl+"."+b64(sign(h+"."+pl));}catch(Exception e){throw new IllegalStateException(e);}}
 AuthPrincipal verify(String token){try{String[] p=token.split("\\.");if(p.length!=3||!MessageDigest.isEqual(sign(p[0]+"."+p[1]),Base64.getUrlDecoder().decode(p[2])))throw new ApiException(ErrorCode.AUTH_REQUIRED); @SuppressWarnings("unchecked") Map<String,Object> c=mapper.readValue(Base64.getUrlDecoder().decode(p[1]),Map.class);if(!"snaphere".equals(c.get("iss"))||((Number)c.get("exp")).longValue()<Instant.now().getEpochSecond())throw new ApiException(ErrorCode.AUTH_REQUIRED);return new AuthPrincipal(UUID.fromString((String)c.get("sub")),UUID.fromString((String)c.get("deviceId")),UserRole.valueOf((String)c.get("role")));}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(ErrorCode.AUTH_REQUIRED);}}
 private byte[] sign(String v)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret,"HmacSHA256"));return mac.doFinal(v.getBytes(StandardCharsets.UTF_8));} private String b64(String s){return b64(s.getBytes(StandardCharsets.UTF_8));}private String b64(byte[] b){return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
}
